def _chapter9_field_recall(mem):
    """docich#3958: let chapter 9's mechanical march see field camps again.

    The monthly pass is off in mechanical mode, so the only live mechanism
    for a general left camping on the field is the map-observed camp recall
    in flows/recall.py. It is not chapter-gated itself: before the boss phase
    ``camp_stays`` is False, so a visible camp is recalled home as in other
    chapters; in the boss phase the same call already re-sends the camp at
    the moving boss. This predicate only decides whether the orchestrator
    hands an idle map frame to that existing flow.
    """
    from docich.hanjuku_speedrun.hanjuku.strategy import corridor
    if corridor.mechanical(mem):
        return True
    # docich#4675: any chapter needs the camp recall when the army cannot
    # concentrate. ch1 3-3 ran with next_order None, four castles at one
    # defender each and four generals unaccounted for: no castle could
    # donate or attack, and the monthly pass had nothing to move. A
    # visible camp's recall is then the only way back to two defenders.
    from docich.hanjuku_speedrun.hanjuku.state.regions import plan as _plan
    if _plan(mem).get('active') is not None:
        return False
    garrison = (mem.get('world') or {}).get('garrison') or {}
    rows = [names for names in garrison.values() if isinstance(names, list)]
    if not rows:
        return False
    # Owner 2026-11-09: a camped general is never recalled home in the moving
    # boss's phase; recall.camp_stays already enforces that inside the flow.
    return all(len(names) < 2 for names in rows)


